Here's a modern MSTest approach:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        var handler = new MockHttpMessageHandler("expected body", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("expected body", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Throws_OnNonSuccessStatus()
    {
        var handler = new MockHttpMessageHandler("", HttpStatusCode.InternalServerError);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Throws_WhenCancelled()
    {
        var handler = new MockHttpMessageHandler("ok", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Lightweight handler — no mocking framework needed
    private sealed class MockHttpMessageHandler(string content, HttpStatusCode status)
        : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return Task.FromResult(new HttpResponseMessage(status)
            {
                Content = new StringContent(content)
            });
        }
    }
}
```

**Key patterns used:**

- **`async Task` test methods** — MSTest natively awaits them; never use `async void`
- **`[Timeout(5000)]`** — per-test timeout in milliseconds; prevents hangs from unawaited tasks (MSTest v3+ uses `CancellationToken`-based cooperative cancellation under the hood)
- **`Assert.ThrowsExactlyAsync`** — MSTest v3.8+ preferred over `ThrowsExceptionAsync`; asserts the exact exception type without matching subclasses
- **Custom `HttpMessageHandler`** — avoids mocking frameworks and gives full control over the HTTP pipeline, including honoring the `CancellationToken`
